import json, sys
from datetime import datetime, timezone


def parse_aware(s):
    """Parse an offset-aware ISO8601 string into a tz-aware datetime.
    Returns None for non-string, null, missing, or naive strings."""
    if not isinstance(s, str):
        return None
    dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
    if dt.tzinfo is None:
        return None
    return dt


def main():
    with open(sys.argv[1], "r", encoding="utf-8") as f:
        data = json.load(f)

    as_of = parse_aware(data["as_of"])
    if as_of is None:
        raise ValueError("invalid as_of")

    items = []
    for r in data.get("reminders", []):
        if r.get("completed"):
            continue
        due = parse_aware(r.get("due"))
        if due is None:
            continue
        if due <= as_of:
            items.append((due, r["id"], r["title"]))

    # sort by actual due instant, then id
    items.sort(key=lambda x: (x[0], x[1]))

    result = []
    for due, rid, title in items:
        utc_dt = due.astimezone(timezone.utc)
        due_utc = utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")
        result.append({"id": rid, "title": title, "due_utc": due_utc})

    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()
